import{_ as o,o as p,c as n,a5 as r}from"./chunks/framework.Cooo9kuv.js";const q=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"830-批量提取文件到输入目录根目录下","日期":"2026-04-13T00:00:00.000Z","修改日期":"2026-04-13T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["文件及文件夹批处理"],"标签":["同名文件处理","子文件夹文件提取","批量提取文件","批量文件移动","文件夹清理","文件整理工具","文件管理软件"]},"headers":[{"level":3,"title":"批量提取文件到输入目录根目录下","slug":"批量提取文件到输入目录根目录下","link":"#批量提取文件到输入目录根目录下","children":[]},{"level":3,"title":"功能特点","slug":"功能特点","link":"#功能特点","children":[]},{"level":3,"title":"📑 程序截图","slug":"📑-程序截图","link":"#📑-程序截图","children":[]},{"level":3,"title":"界面介绍","slug":"界面介绍","link":"#界面介绍","children":[]},{"level":3,"title":"基本操作指南","slug":"基本操作指南","link":"#基本操作指南","children":[]},{"level":3,"title":"实际使用场景示例","slug":"实际使用场景示例","link":"#实际使用场景示例","children":[]},{"level":3,"title":"注意事项","slug":"注意事项","link":"#注意事项","children":[]},{"level":3,"title":"📑 程序使用环境及相关说明","slug":"📑-程序使用环境及相关说明","link":"#📑-程序使用环境及相关说明","children":[]},{"level":3,"title":"常见问题解答","slug":"常见问题解答","link":"#常见问题解答","children":[]},{"level":3,"title":"📑 程序使用说明","slug":"📑-程序使用说明","link":"#📑-程序使用说明","children":[]}],"relativePath":"md/文件及文件夹批处理/830-批量提取文件到输入目录根目录下.md","filePath":"md/文件及文件夹批处理/830-批量提取文件到输入目录根目录下.md"}'),e={name:"md/文件及文件夹批处理/830-批量提取文件到输入目录根目录下.md"};function a(s,t,l,g,i,u){return p(),n("div",null,[...t[0]||(t[0]=[r('<h3 id="批量提取文件到输入目录根目录下" tabindex="-1">批量提取文件到输入目录根目录下 <a class="header-anchor" href="#批量提取文件到输入目录根目录下" aria-label="Permalink to &quot;批量提取文件到输入目录根目录下&quot;">​</a></h3><p>能够帮助您快速将指定文件夹及其所有子文件夹中的文件提取到根目录，让文件整理变得简单高效。无论是整理下载文件夹、照片库，还是项目文档，这款工具都能帮您轻松完成文件提取工作，避免繁琐的手动操作。</p><h3 id="功能特点" tabindex="-1">功能特点 <a class="header-anchor" href="#功能特点" aria-label="Permalink to &quot;功能特点&quot;">​</a></h3><p><strong>批量提取</strong>：一键将所有子文件夹中的文件移动到根目录</p><p><strong>同名文件智能处理</strong>：提供三种冲突处理模式，灵活应对同名文件</p><p><strong>空文件夹清理</strong>：可选择自动删除提取后的空文件夹</p><h3 id="📑-程序截图" tabindex="-1">📑 程序截图 <a class="header-anchor" href="#📑-程序截图" aria-label="Permalink to &quot;📑 程序截图&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251022190938176113137848149.png" alt=""></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251022191125176113148559717.jpg" alt=""></p><h3 id="界面介绍" tabindex="-1">界面介绍 <a class="header-anchor" href="#界面介绍" aria-label="Permalink to &quot;界面介绍&quot;">​</a></h3><p><strong>根文件夹选择区</strong>：用于指定需要处理的根文件夹</p><p><strong>同名文件处理选项</strong>：包含三个单选按钮</p><p>覆盖：同名文件将被替换</p><p>跳过：遇到同名文件时不进行处理</p><p>添加数字序列：为同名文件添加数字后缀以避免冲突（默认选项）</p><p><strong>删除空文件夹复选框</strong>：勾选后将自动删除提取文件后的空文件夹</p><h3 id="基本操作指南" tabindex="-1">基本操作指南 <a class="header-anchor" href="#基本操作指南" aria-label="Permalink to &quot;基本操作指南&quot;">​</a></h3><p><strong>选择根文件夹</strong>：</p><p>点击&quot;浏览&quot;按钮</p><p>在弹出的文件夹选择对话框中，找到并选择需要处理的根文件夹</p><p>点击&quot;确定&quot;按钮</p><p><strong>设置处理选项</strong>：</p><p>选择合适的同名文件处理方式（覆盖/跳过/添加数字序列）</p><p>根据需要勾选&quot;删除空文件夹&quot;选项</p><p><strong>执行操作</strong>：</p><p>点击&quot;开始&quot;按钮启动处理过程</p><p>观察日志显示区的进度信息</p><p>等待操作完成（日志显示&quot;完成&quot;）</p><p><strong>查看结果</strong>：</p><p>所有子文件夹中的文件已被移动到根文件夹</p><p>根据选择，空文件夹可能已被删除</p><h3 id="实际使用场景示例" tabindex="-1">实际使用场景示例 <a class="header-anchor" href="#实际使用场景示例" aria-label="Permalink to &quot;实际使用场景示例&quot;">​</a></h3><p><strong>场景一：整理下载文件夹</strong></p><p><strong>需求</strong>：从多个下载子文件夹中提取所有文件到主下载文件夹，并清理空文件夹</p><p><strong>操作步骤</strong>：</p><p>选择包含多个下载子文件夹的主文件夹作为根文件夹</p><p>选择&quot;添加数字序列&quot;作为同名文件处理方式（避免文件覆盖）</p><p>勾选&quot;删除空文件夹&quot;选项</p><p>点击&quot;开始&quot;按钮</p><p>等待处理完成，所有下载的文件将统一存放在主文件夹中，原有的空文件夹被自动清理</p><p><strong>场景二：照片库整理</strong></p><p><strong>需求</strong>：将按日期分类的照片文件夹中的所有照片移动到主照片文件夹，保留最新版本</p><p><strong>操作步骤</strong>：</p><p>选择照片库主文件夹作为根文件夹</p><p>选择&quot;覆盖&quot;作为同名文件处理方式（保留最新版本的同名照片）</p><p>取消勾选&quot;删除空文件夹&quot;（保留日期分类结构）</p><p>点击&quot;开始&quot;按钮</p><p>处理完成后，所有照片都在主文件夹中，同时保留了原有的日期文件夹结构</p><p><strong>场景三：项目文档合并</strong></p><p><strong>需求</strong>：将多个项目子目录中的文档合并到项目根目录，但不覆盖现有文件</p><p><strong>操作步骤</strong>：</p><p>选择项目根目录作为根文件夹</p><p>选择&quot;跳过&quot;作为同名文件处理方式（保留根目录中已有的文件）</p><p>取消勾选&quot;删除空文件夹&quot;（保留项目结构）</p><p>点击&quot;开始&quot;按钮</p><p>处理完成后，所有子目录中的文档都被移动到根目录，根目录中已存在的同名文件不会被影响</p><h3 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h3><p><strong>文件覆盖风险</strong>：选择&quot;覆盖&quot;选项时，同名文件将被替换，无法恢复</p><p><strong>权限问题</strong>：确保您对选择的文件夹具有读写权限</p><h3 id="📑-程序使用环境及相关说明" tabindex="-1">📑 程序使用环境及相关说明 <a class="header-anchor" href="#📑-程序使用环境及相关说明" aria-label="Permalink to &quot;📑 程序使用环境及相关说明&quot;">​</a></h3><p><strong>1、适用的系统环境说明</strong>： win7及以上64位win操作系统 ，  **注意事项：**win32位系统以及mac系统需要额外定制开发</p><p><strong>2、关于使用限制</strong>：①无需注册、登录等限制，直接使用，  ②没有电脑台数限制，  ③无使用时间限制、不联网本地使用、确保数据安全</p><p><strong>3、程序如何安装</strong>：不需要安装，按照说明使用即可。</p><p><strong>特别注意</strong>：请先测试，注意备份原文件，之后再批量使用，避免不可逆损失。</p><h3 id="常见问题解答" tabindex="-1">常见问题解答 <a class="header-anchor" href="#常见问题解答" aria-label="Permalink to &quot;常见问题解答&quot;">​</a></h3><p><strong>Q: 程序运行时提示错误或无响应怎么办？</strong></p><p>A: 请检查以下几点：1) 是否有足够的磁盘空间；2) 是否对目标文件夹有读写权限；3) 重启程序后重试；4) 如果仍然有问题，建议备份数据后重新安装程序</p><p><strong>Q: 同名文件处理选项有什么区别？</strong></p><p>A: &quot;覆盖&quot;会替换同名文件；&quot;跳过&quot;会忽略同名文件，保持原样；&quot;添加数字序列&quot;会为同名文件添加数字后缀（如file_1.txt, file_2.txt）以避免冲突</p><p><strong>Q: 为什么有些文件没有被移动？</strong></p><p>A: 可能的原因：1) 文件正在被其他程序使用；2) 您选择了&quot;跳过&quot;选项且遇到同名文件；3) 对该文件没有访问权限</p><p><strong>Q: 处理大量文件时程序会不会崩溃？</strong></p><p>A: 程序使用多线程处理，即使处理大量文件也应该保持响应。但如果文件数量非常庞大（数万或更多），可能需要较长时间，请耐心等待</p><p><strong>Q: 我可以同时处理多个文件夹吗？</strong></p><p>A: 目前版本不支持同时处理多个文件夹，可以多开几个程序进行处理。</p><h3 id="📑-程序使用说明" tabindex="-1">📑 程序使用说明 <a class="header-anchor" href="#📑-程序使用说明" aria-label="Permalink to &quot;📑 程序使用说明&quot;">​</a></h3><p><strong>双击使用即可，可执行文件（.exe文件），双击该文件即可启动工具。</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251022191302176113158223889.png" alt=""></p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/2104.html" target="_blank" rel="noreferrer">https://www.softbangong.com/2104.html</a></p>',80)])])}const d=o(e,[["render",a]]);export{q as __pageData,d as default};
